 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Read palette from the repeated color strip at the bottom.
    palette = None
    for r in range(h - 1, -1, -1):
        vals = [v for v in grid[r] if v]
        if len(vals) >= 2 and len(set(vals)) == len(vals):
            palette = vals
            break
    if palette is None:
        return [row[:] for row in grid]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    minr, maxr = min(r for r, c in pts), max(r for r, c in pts)
    minc, maxc = min(c for r, c in pts), max(c for r, c in pts)
    shape = [[grid[r][c] == 1 for c in range(minc, maxc + 1)] for r in range(minr, maxr + 1)]
    sh, sw = len(shape), len(shape[0])
    # Sequence of example's complete copies establishes the shape height; use palette
    # colors to recolor that template, keeping it centered on its original slot.
    copies = len(palette)
    out = [[0] * w for _ in range(h)]
    top = minr - (copies // 2) * sh
    for k, color in enumerate(palette):
        for dr in range(sh):
            rr = top + k * sh + dr
            if 0 <= rr < h:
                for dc in range(sw):
                    if shape[dr][dc]:
                        out[rr][minc + dc] = color
    # The figure's row coordinates indicate which palette entry is central.
    return out
