    keycols={c for c,v in cols}
    pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]==1 and c not in keycols}
    comps=[]
    while pts:
        seed=pts.pop(); comp={seed}; stack=[seed]
        while stack:
            r,c=stack.pop()
            for q in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
                if q in pts: pts.remove(q);comp.add(q);stack.append(q)
        comps.append(comp)
    comp=max(comps,key=len)
    minr,maxr=min(r for r,c in comp),max(r for r,c in comp)
    minc,maxc=min(c for r,c in comp),max(c for r,c in comp)
    shape=[[ (minr+dr,minc+dc) in comp for dc in range(maxc-minc+1)] for dr in range(maxr-minr+1)]
